mgc_code:
def to_rgb(hsv):
    """Converts a color from HSV to a hex RGB.

    HSV should be in range 0..1, though hue wraps around. Output is a 
    hexadecimal color value as used by CSS, HTML and SVG"""
    h, s, v = hsv
    h = h % 1
    i = int(h * 6)
    f = h * 6 - i
    p = v * (1 - s)
    q = v * (1 - f * s)
    t = v * (1 - (1 - f) * s)
    r, g, b = 0, 0, 0
    if i == 0:
        r, g, b = v, t, p
    elif i == 1:
        r, g, b = q, v, p
    elif i == 2:
        r, g, b = p, v, t
    elif i == 3:
        r, g, b = p, q, v
    elif i == 4:
        r, g, b = t, p, v
    elif i == 5:
        r, g, b = v, p, q
    return "#%02x%02x%02x" % (int(r * 255), int(g * 255), int(b * 255))

