    """
    check arguments against a command_line_dataframe.
    checks that:
    all arguments are valid
    all required arguments are present
    default values are used where needed
    """
    for argument in arguments:
        if argument not in data_frame.columns:
            raise ValueError(f"Argument '{argument}' is not valid.")
    for column in data_frame.columns:
        if column not in arguments and data_frame[column].notnull().any():
            raise ValueError(f"Required argument '{column}' is missing.")
