def past_datetime(start='-30d'):
    """
    Returns a ``datetime`` object in the past between 1 second ago and the
    specified ``start``. ``start`` can be a string, another datetime, or a
    timedelta. If it's a string, it must start with `-`, followed by and integer
    and a unit, Eg: ``'-30d'``. Defaults to `'-30d'`

    Valid units are:
    * ``'years'``, ``'y'``
    * ``'weeks'``, ``'w'``
    * ``'days'``, ``'d'``
    * ``'hours'``, ``'h'``
    * ``'minutes'``, ``'m'``
    * ``'seconds'``, ``'s'``
    """
    if isinstance(start, str):
        match = re.match(r'^-(\d+)(\w+)$', start)
        if match:
            amount, unit = match.groups()
            amount = int(amount)
            if unit in ('years', 'y'):
                start = datetime.timedelta(days=365*amount)
            elif unit in ('weeks', 'w'):
                start = datetime.timedelta(days=7*amount)
            elif unit in ('days', 'd'):
                start = datetime.timedelta(days=amount)
            elif unit in ('hours', 'h'):
                start = datetime.timedelta(hours=amount)
            elif unit in ('minutes','m'):
                start = datetime.timedelta(minutes=amount)
            elif unit in ('seconds','s'):
                start = datetime.timedelta(seconds=amount)
            else:
                raise ValueError(f'Invalid unit: {unit}')
        else:
            raise ValueError(f'Invalid start: {start}')
    elif isinstance(start, datetime.datetime):
        start = datetime.datetime.now() - start
    elif not isinstance(start, datetime.timedelta):
        raise TypeError(f'Invalid type for start: {type(start)}')
    end = datetime.datetime.now() - datetime.timedelta(seconds=1)
    return end - datetime.timedelta(seconds=start.total_seconds())

