def reverse_action(self, action):
    """Transform an SC2-style action into an agent-style action.

    This should be the inverse of `transform_action`.

    Args:
      action: a `sc_pb.Action` to be transformed.

    Returns:
      A corresponding `actions.FunctionCall`.

    Raises:
      ValueError: if it doesn't know how to transform this action.
    """
    if action.action_id == 1:
        return actions.FunctionCall(action.action_id, [action.target_unit_tag])
    elif action.action_id == 2:
        return actions.FunctionCall(action.action_id, [action.target_unit_tag, action.target_pos.x, action.target_pos.y])
    else:
        raise ValueError("Unknown action ID: {}".format(action.action_id))

