def hashable(cls):
    """Makes sure the class is hashable.

    Needs a working __eq__ and __hash__ and will add a __ne__.
    """
    if not hasattr(cls, "__eq__") or not hasattr(cls, "__hash__"):
        raise TypeError("Class must have __eq__ and __hash__ methods")

    if not hasattr(cls, "__ne__"):
        def __ne__(self, other):
            return not self.__eq__(other)
        cls.__ne__ = __ne__

