    """An agglutination diphthong that ends in /u, y/ usually contains a
    syllable boundary when -C# or -CCV follow, e.g., [lau.ka.us],
    [va.ka.ut.taa]."""
    WORD = _split_consonants_and_vowels(word)

    for k, v in WORD.iteritems():

