    :func:`min` (or :func:`max` if ``reverse=True``) for the underlying
    implementation."""
    if reverse:
        return iter(sorted(itertools.chain(*iterables), key=key, reverse=True))
    else:
        return iter(sorted(itertools.chain(*iterables), key=key))

