def cmd(tgt,
        fun,
        arg=(),
        timeout=None,
        tgt_type='glob',
        ret='',
        kwarg=None,
        ssh=False,
        **kwargs):
    """
    .. versionchanged:: 2017.7.0
        The ``expr_form`` argument has been renamed to ``tgt_type``, earlier
        releases must use ``expr_form``.

    Assuming this minion is a master, execute a salt command

    CLI Example:

    .. code-block:: bash

        salt '*' saltutil.cmd
    """
    if not tgt or not fun:
        return {}
    if tgt_type not in ('glob', 'list', 'nodegroup', 'pillar', 'grain', 'compound'):
        tgt_type = 'glob'
    if not isinstance(arg, tuple):
        arg = (arg,)
    if not isinstance(kwarg, dict):
        kwarg = {}
    if not ret:
        ret = ''
    if not timeout:
        timeout = 0
    if not ssh:
        ssh = False
    result = {}
    minions = get_minions(tgt, tgt_type)
    for minion in minions:
        result[minion] = execute_command(minion, fun, arg, timeout, ret, kwarg, ssh)

    return result

