def GreedyPolyMatchDist(self, shape):
    """
    Tries a greedy matching algorithm to match self to the
    given shape.  Returns the maximum distance in meters of
    any point in self to its matched point in shape under the
    algorithm.

    Args: shape, a Poly object.
    """
    if not isinstance(shape, Poly):
        raise TypeError("shape must be a Poly object")
    if len(self.points)!= len(shape.points):
        raise ValueError("self and shape must have the same number of points")
    distances = []
    for i, point in enumerate(self.points):
        distances.append(point.dist(shape.points[i]))
    return max(distances)

