        if response_type!= 'code':
            raise ValueError('Invalid response type')
        if not client_id:
            raise ValueError('Missing client ID')
        if not self.client_id_exists(client_id):
            raise ValueError('Invalid client ID')
        if redirect_uri and not self.validate_redirect_uri(client_id, redirect_uri):
            raise ValueError('Invalid redirect URI')
        if scope and not self.validate_scope(scope):
            raise ValueError('Invalid scope')
        if audience and not self.validate_audience(audience):
            raise ValueError('Invalid audience')
