        for j in range(ci_X.shape[1]):
            a = ci_X[i, j] * ntrials
            b = ntrials - a
            Plow[i, j] = beta.ppf((1 - ci) / 2, a, b)
            Phigh[i, j] = beta.ppf(1 - (1 - ci) / 2, a, b)

