    """Calculates SHA256 digest of a file.

    Args:
        source: either a file-like object or a path to file
    """
    if hasattr(source,'read'):
        file_obj = source
    else:
        file_obj = open(source, 'rb')
    digest = hashlib.sha256()
    while True:
        chunk = file_obj.read(4096)
        if not chunk:
            break
        digest.update(chunk)
    file_obj.close()
    return digest.hexdigest()

